def test_install_removes_the_old_local_hard_eng_copy(
    installer: ModuleType, tmp_path: Path
) -> None:
    repository(tmp_path)
    payload = tmp_path / ".agents/hard-eng/current"
    (payload / "skills/plain-english").mkdir(parents=True)
    (payload / "skills/plain-english/SKILL.md").write_text("old\n")
    (tmp_path / ".claude/skills").mkdir(parents=True)
    (tmp_path / ".claude/skills/plain-english").symlink_to(
        "../../.agents/hard-eng/current/skills/plain-english"
    )
    (payload / "output-styles").mkdir()
    (payload / "output-styles/plain-english.md").write_text("old\n")
    (tmp_path / ".claude/output-styles").mkdir()
    (tmp_path / ".claude/output-styles/plain-english.md").symlink_to(
        "../../.agents/hard-eng/current/output-styles/plain-english.md"
    )
    (tmp_path / "CLAUDE.local.md").write_text("@.agents/hard-eng/current/AGENTS.md\n")
    old = f"bash {payload}/scripts/hooks/agent-hook.sh claude pretooluse"
    local = {
        "outputStyle": "Plain English",
        "permissions": {"allow": ["Bash(ls)"]},
        "hooks": {
            "PreToolUse": [
                {"hooks": [{"type": "command", "command": old}]},
                {"hooks": [{"type": "command", "command": "bash .hard-eng/hook.sh"}]},
            ]
        },
    }
    (tmp_path / ".claude/settings.local.json").write_text(json.dumps(local))
    (tmp_path / ".codex").mkdir()
    (tmp_path / ".codex/config.toml").write_text(
        'model = "o3"\nproject_doc_max_bytes = 65536 # Generated by Hard Eng\n'
    )
    exclude = tmp_path / ".git/info/exclude"
    exclude.write_text(
        "*.log\n\n# >>> hard-eng repository fallback >>>\n/.agents/hard-eng/\n"
        "/.claude/settings.local.json\n/.claude/output-styles/plain-english.md\n"
        "# <<< hard-eng repository fallback <<<\n"
    )
    installer.install(tmp_path)
    assert not (tmp_path / ".agents/hard-eng").exists()
    assert not (tmp_path / ".claude/skills/plain-english").is_symlink()
    assert not (tmp_path / ".claude/output-styles/plain-english.md").is_symlink()
    assert not (tmp_path / "CLAUDE.local.md").exists()
    assert json.loads((tmp_path / ".claude/settings.local.json").read_text()) == {
        "permissions": {"allow": ["Bash(ls)"]}
    }
    codex = (tmp_path / ".codex/config.toml").read_text()
    assert codex.startswith('model = "o3"\n')
    assert "project_doc_max_bytes" not in codex
    assert exclude.read_text() == (
        "*.log\n\n/.agents/hard-eng/\n/.claude/settings.local.json\n"
        "/.claude/output-styles/plain-english.md\n"
    )
    assert not (tmp_path / "CLAUDE.md").exists()


def test_install_leaves_linked_legacy_folders_untouched(
    installer: ModuleType, tmp_path: Path
) -> None:
    shared = tmp_path / "shared"
    (shared / "agents/hard-eng/current").mkdir(parents=True)
    (shared / "claude").mkdir()
    settings = '{"outputStyle": "Plain English"}'
    (shared / "claude/settings.local.json").write_text(settings)
    root = tmp_path / "project"
    root.mkdir()
    repository(root)
    (root / ".agents").symlink_to(shared / "agents", target_is_directory=True)
    (root / ".claude").symlink_to(shared / "claude", target_is_directory=True)
    with pytest.raises(ValueError, match=r"\.agents|\.claude"):
        installer.install(root)
    assert (shared / "agents/hard-eng/current").is_dir()
    assert (shared / "claude/settings.local.json").read_text() == settings


