def test_session_start_removes_untracked_fallback_files(
    release: tuple[Path, Path, str], monkeypatch: pytest.MonkeyPatch
) -> None:
    _, target, _ = release
    (target / "AGENTS.override.md").write_text(OLD_FILES["AGENTS.override.md"])
    (target / "CLAUDE.local.md").write_text("@.agents/hard-eng/current/AGENTS.md\n")
    exclude = target / ".git/info/exclude"
    before = exclude.read_text()
    exclude.write_text(
        before + "# >>> hard-eng repository fallback >>>\n/AGENTS.override.md\n"
        "/CLAUDE.local.md\n# <<< hard-eng repository fallback <<<\n"
    )
    monkeypatch.setattr(update, "latest_verified", Mock(return_value=None))
    update.update(target)
    assert not (target / "AGENTS.override.md").exists()
    assert not (target / "CLAUDE.local.md").exists()
    assert exclude.read_text() == before + "/AGENTS.override.md\n/CLAUDE.local.md\n"
    assert git(target, "status", "--porcelain") == ""


def test_install_refuses_linked_local_settings_that_run_the_old_copy(
    installer: ModuleType, tmp_path: Path
) -> None:
    root = tmp_path / "project"
    root.mkdir()
    repository(root)
    (root / ".agents/hard-eng/current").mkdir(parents=True)
    shared = tmp_path / "settings.local.json"
    command = "bash .agents/hard-eng/current/scripts/hooks/agent-hook.sh"
    shared.write_text(
        json.dumps({"hooks": {"Stop": [{"hooks": [{"command": command}]}]}})
    )
    (root / ".claude").mkdir()
    (root / ".claude/settings.local.json").symlink_to(shared)
    with pytest.raises(ValueError, match="settings.local.json"):
        installer.install(root)
    assert (root / ".agents/hard-eng/current").is_dir()


def test_candidate_ignores_base_changes_the_branch_lacks(
    release: tuple[Path, Path, str],
) -> None:
    source, target, _ = release
    commit(source, "verified source candidate")
    (target / "package.json").unlink()
    config = json.loads((target / "hard-eng.gates.json").read_text())
    config["shared"][0]["command"] = ["python3", "-c", "raise SystemExit(0)"]
    (target / "hard-eng.gates.json").write_text(json.dumps(config))
    shared = target / "shared.py"
    shared.write_text("# one\n# two\n# three\nVALUE = 1\n")
    git(target, "branch", "-M", "main")
    commit(target, "remote baseline")
    remote = target.parent / "remote.git"
    git(target, "clone", "--bare", str(target), str(remote))
    git(target, "remote", "add", "origin", str(remote))
    git(target, "switch", "-c", "feature/update")
    git(target, "switch", "main")
    shared.write_text("VALUE = 2\n")
    commit(target, "base moves on")
    git(target, "push", "-q", "--no-verify", "origin", "main")
    git(target, "switch", "feature/update")
    changes: dict[str, str | None] = {"new-managed.mjs": "export const value = 1;\n"}
    update.verify_candidate(target, source, changes, {}, target.parent / "candidate")
